/* Canonical quotation pages; business decisions come from the service DTOs. */
window.WorkspacePages = (() => {
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const label = value => String(value).replaceAll('_', ' ');
  const link = (id, text) => `<a class="btn btn-sm btn-outline" href="#/quotations/${e(id)}">${e(text)}</a>`;
  const request = async (path, body) => {
    const epoch=window.freightRouteEpoch;
    const response=await fetch(path, body === undefined ? {} : {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)});
    const text=await response.text();
    let data={};
    let invalidJson=false;
    if(text){try{data=JSON.parse(text);}catch{invalidJson=true;data={error:text.slice(0,400)};}}
    if(epoch!==window.freightRouteEpoch)throw new DOMException('Navigation changed','AbortError');
    if(response.status===401){location.href='/login'; throw Error('Please sign in');}
    if(!response.ok) throw Error(data.error || `Request failed (${response.status})`);
    if(invalidJson) throw Error('The server returned an unreadable response. Please reload and try again.');
    return data;
  };
  const root = () => document.getElementById('view');
  const notice = text => {const node=document.getElementById('workspace-notice'); if(node) node.textContent=text;};
  const run = async (button, action) => {button.disabled=true; try{await action();}catch(error){if(error.name!=='AbortError')notice(error.message);}finally{button.disabled=false;}};
  const heading = (title, guide) => {document.getElementById('page-title').textContent=title; document.getElementById('page-guide').textContent=guide;};
  const frame = html => {root().innerHTML=`<p id="workspace-notice" role="status" aria-live="polite"></p>${html}`;};
  async function list(archived=false) {
    heading(archived?'Archived quotations':'Quotations',archived?'Preserved decisions, sources and correspondence.':'Review received quotations, resolve missing information, then approve and import.');
    const [rows, otherRows, messages, drafts, localDrafts] = await Promise.all([request(`/api/workspace/quotes?archived=${archived}&include_intake=true`),request(`/api/workspace/quotes?archived=${!archived}`),request('/api/gmail/inbox'),request('/api/supplier-email-drafts'),request('/api/drafts')]);
    const proposals=archived?[]:await request('/api/destination-proposals');
    const proposalStatus = status => ({ready_for_approval:'Awaiting approval',approved:'Approved · awaiting import',imported:'Imported successfully',rejected:'Rejected',needs_information:'Missing information'}[status] || label(status));
    const proposalTone = status => status==='imported'?'badge-success':status==='approved'?'badge-info':status==='ready_for_approval'?'badge-warning':status==='rejected'?'badge-ghost':'badge-error';
    const readyProposalCount=proposals.filter(p=>p.status==='ready_for_approval').length;
    const approvedProposalCount=proposals.filter(p=>p.status==='approved').length;
    const proposalHTML=proposals.length?`<details class="collapse collapse-arrow proposal-workspace" id="proposal-workspace">
      <summary class="collapse-title proposal-workspace-summary">
        <span class="proposal-summary-label"><strong id="proposal-heading">Supplier Master Database records</strong><small>${proposals.length} quotation ${proposals.length===1?'record':'records'} prepared for one unified database</small></span>
        <span class="badge badge-warning">${readyProposalCount} awaiting approval</span><span class="badge badge-info">${approvedProposalCount} awaiting import</span>
      </summary>
      <div class="collapse-content"><div class="proposal-list">${[...new Set(proposals.map(p=>p.intake_id))].map(sourceId=>{const proposal=proposals.find(p=>p.intake_id===sourceId);return `<section class="proposal-source"><h3 title="${e(proposal.source_name||'')}">Quotation source <small>${e(proposal.source_name||'Original document')}</small></h3>${proposals.filter(p=>p.intake_id===sourceId).map(p=>{
        const fieldTone=status=>status==='high_confidence'?'badge-success':status==='uncertain'?'badge-warning':status==='missing'?'badge-error':status==='not_applicable'?'badge-ghost':status==='supplier_master'?'badge-info':'badge-neutral';
        const fieldLabel=f=>f.label||f.name.replaceAll('_',' ');
        const detailRows=p.schema.filter(f=>f.scope!=='system').map(f=>{
          const status=p.field_status?.[f.name]||((p.missing||[]).includes(f.name)?'missing':(p.values||{})[f.name]!=null?'high_confidence':'not_stated');
          const score=p.confidence?.[f.name];
          const statusText=status==='high_confidence'?'Green · high confidence':status==='uncertain'?'Yellow · confirm with supplier':status==='missing'?'Red · missing from quotation':status==='not_applicable'?'Not applicable':status==='supplier_master'?'Supplier master record':'Not stated';
          const confidenceText=score==null?'—':`${Math.round(Number(score)*100)}%`;
          const raw=p.values?.[f.name];
          const value=status==='missing'?'Missing from quotation':status==='not_applicable'?'Not applicable':raw==null||raw===''?'Not stated':String(raw);
          const excerpt=p.evidence?.[f.name];
          const reason=p.explanations?.[f.name];
          return `<tr><td><strong>${e(fieldLabel(f))}</strong>${f.required?' <span class="badge badge-xs badge-warning">Required</span>':''}</td><td>${e(value)}${['high_confidence','uncertain'].includes(status)?` <span class="badge badge-sm ${fieldTone(status)}">${e(confidenceText)}</span>`:''}</td><td><span class="badge badge-sm ${fieldTone(status)}">${e(statusText)}</span>${reason?`<p class="meta">${e(reason)}</p>`:''}${excerpt?`<details><summary>Source evidence</summary><blockquote>${e(excerpt)}</blockquote></details>`:status==='missing'?'<span class="meta">Supplier clarification is required.</span>':''}</td></tr>`;
        }).join('');
        const attachedDrafts=drafts.filter(d=>d.destination_proposal_id===p.id&&d.status!=='cancelled');
        return `<details class="proposal-item"><summary><span class="proposal-destination"><strong>${e(p.database_name||'Supplier Master Database')}</strong><small>${Object.values(p.values||{}).filter(v=>v!==null&&v!==undefined&&v!=='').length} values · ${(p.uncertain||[]).length} uncertain · ${(p.missing||[]).length} missing</small></span><span class="badge badge-sm ${proposalTone(p.status)}">${e(proposalStatus(p.status))}</span><span class="proposal-expand">Review fields</span></summary><div class="proposal-content"><p class="meta">One quotation becomes a separate row in the unified supplier master. Supplier-level values are labeled separately from quotation evidence.</p>${!p.schema_current?'<div class="alert alert-warning"><span>This extraction used an older database schema. Reanalyze it to check every current quotation field.</span></div>':''}<div class="row"><a class="btn btn-sm btn-outline" href="#/proposals/${e(p.id)}">Open extraction summary</a>${!p.schema_current?`<button class="btn btn-sm btn-warning" data-reanalyze="${e(p.id)}">Reanalyze with current fields</button>`:''}</div><div class="overflow-x-auto"><table class="table table-sm"><thead><tr><th>Quotation field</th><th>Extracted value and confidence</th><th>Status, reason and evidence</th></tr></thead><tbody>${detailRows}</tbody></table></div>${p.issues?.length?p.issues.map(i=>`<p class="proposal-issues">${e(i)}</p>`).join(''):''}${attachedDrafts.length?`<section class="proposal-drafts"><h4>Supplier clarification drafts</h4>${attachedDrafts.map(d=>`<article class="workspace-gap row spread"><div><span class="badge badge-sm ${d.draft_type==='supplier_confirmation'?'badge-warning':'badge-error'}">${e(d.draft_type==='supplier_confirmation'?'Supplier confirmation':'Missing information')}</span><p>${e(d.subject)} · ${e(d.recipient)}</p></div><a class="btn btn-sm btn-outline" href="#/email-draft/${e(d.id)}">Review draft</a></article>`).join('')}<p class="meta">Drafts are saved locally. Sending requires your approval and explicit send action.</p></section>`:''}<div class="row">${p.status==='ready_for_approval'?`<button class="btn btn-sm btn-primary" data-proposal="${e(p.id)}" data-decision="approve">Approve record</button>`:''}${p.status==='approved'?`<button class="btn btn-sm btn-primary" data-proposal="${e(p.id)}" data-decision="import">Import approved record</button>`:''}${!['imported','rejected'].includes(p.status)?`<button class="btn btn-sm btn-ghost" data-proposal="${e(p.id)}" data-decision="reject">Reject quotation record</button>`:''}${p.status==='approved'?'<span class="meta">Approval is complete; import is still required.</span>':''}${p.status==='imported'?'<span class="meta">Imported into the single supplier master.</span>':''}</div></div></details>`;
      }).join('')}</section>`}).join('')}</div></div>
    </details>`:'';
    const localPending=localDrafts.filter(d=>d.id===d.question_set_id && ['draft','approved'].includes(d.status) && !drafts.some(t=>t.clarification_turn_id===d.id)).length;
    const draftCount=drafts.filter(d=>['draft','approved'].includes(d.status)).length+localPending;
    const replyCount=messages.filter(m=>m.processing_status==='reply_needs_linking').length;
    const attentionRows=rows.filter(r=>r.can_approve||r.can_import||r.conflicts.length||r.missing.length||['Reading failed','Check email delivery','Needs review','Confirm document type'].includes(r.stage));
    const processingCount=rows.filter(r=>r.record_type==='intake'&&['Reading','Received'].includes(r.stage)).length;
    const reviewCount=rows.filter(r=>r.can_approve).length;
    const importedCount=rows.filter(r=>r.review_status==='imported').length;
    const attentionCount=attentionRows.length+draftCount+replyCount+proposals.filter(p=>['ready_for_approval','approved'].includes(p.status)).length;
    let activeFilter='all'; let quickFilter='all';
    const filterTab=(key,title,count,tone)=>`<button type="button" class="tab quote-filter-tab ${key==='all'?'tab-active':''}" role="tab" aria-selected="${key==='all'}" aria-controls="quote-table-panel" data-quote-filter="${key}"><span>${title}</span><span class="badge badge-sm ${key==='all'?'badge-primary':tone}">${count}</span></button>`;
    const actionItem=(key,title,count,description,filter,href,tone)=>count?`<button class="btn btn-sm attention-item ${tone}" data-quick-filter="${filter}" ${href?`data-action-href="${href}"`:''}><span class="attention-copy"><strong>${title}</strong><small>${description}</small></span><span class="badge badge-sm">${count}</span></button>`:'';
    frame(`${!archived?`<header class="quote-page-head"><div><p class="quote-kicker">FREIGHT OPERATIONS</p><h2>Quotations</h2><p>Track incoming offers, review extracted details, and manage supplier records.</p></div><div class="quote-page-actions"><a class="btn btn-outline" href="#/drafts" aria-label="Open clarification drafts">Drafts <span class="badge badge-sm badge-ghost">${draftCount}</span></a><a class="btn btn-primary" href="#/inbox">Open Mailbox <span aria-hidden="true">→</span></a></div></header>
      <section class="quote-filter-section" aria-label="Quotation status filters"><div class="tabs tabs-box quote-filter-tabs" role="tablist" aria-label="Filter quotations">${filterTab('all','All',rows.length,'badge-ghost')}${filterTab('attention','Needs Attention',attentionRows.length,'badge-warning')}${filterTab('processing','Processing',processingCount,'badge-info')}${filterTab('imported','Imported',importedCount,'badge-success')}</div></section>
      ${attentionCount?`<details class="collapse collapse-arrow action-summary"><summary class="collapse-title action-summary-title"><span><strong>Action required</strong><small>Only items that need your input</small></span><span class="badge badge-warning">${attentionCount}</span></summary><div class="collapse-content"><div class="attention-list">${actionItem('review','Ready for quotation review',reviewCount,'Check extracted details before approval','review',null,'primary')}${actionItem('gaps','Information or evidence to resolve',rows.filter(r=>r.conflicts.length||r.missing.length).length,'Some quotation details need attention','gaps',null,'warning')}${actionItem('proposals','Database records awaiting approval',readyProposalCount,'Review each matched destination','proposals',null,'info')}${actionItem('proposal-import','Approved records to import',approvedProposalCount,'Approval is complete; import is a separate step','proposals',null,'info')}${actionItem('drafts','Supplier replies or drafts',draftCount,'Review correspondence before sending','drafts','#/drafts','info')}${actionItem('replies','Replies to link',replyCount,'Match each supplier reply to its quotation','replies','#/inbox','warning')}</div></div></details>`:''}${proposalHTML}`:''}
      <div class="quote-list-head"><div><h3>${archived?'Archived quotations':'Quotation inbox'}</h3><p>${archived?'Preserved sources, correspondence, and decisions.':'Search and filter your received freight offers.'}</p></div><div class="quote-controls"><input id="quote-search" class="input input-bordered input-sm" type="search" aria-label="Search quotations" placeholder="Search supplier, route or reference"><select id="stage-filter" class="select select-bordered select-sm" aria-label="Processing status"><option value="">All statuses</option>${[...new Set(rows.map(r=>r.stage))].map(s=>`<option value="${e(s)}">${e(s)}</option>`).join('')}</select><select id="quote-sort" class="select select-bordered select-sm" aria-label="Sort quotations"><option value="received">Newest received</option><option value="supplier">Supplier</option><option value="lane">Route</option></select></div></div>
      <div id="quote-table-panel" class="overflow-x-auto quotation-table-wrap" role="region" aria-label="Quotation results" tabindex="0"><table class="table table-zebra quotation-table"><thead><tr><th scope="col">Supplier / reference</th><th scope="col">Freight route</th><th scope="col">Quotation price</th><th scope="col">Received</th><th scope="col">Completeness</th><th scope="col">Processing stage</th><th scope="col">Next action</th></tr></thead><tbody id="quote-rows"></tbody></table><p id="quote-empty" class="quote-empty" hidden>No quotations match these filters.</p></div><div id="quote-mobile-list" class="quote-mobile-list" aria-label="Quotation cards"></div>
`);

    root().querySelectorAll('[data-proposal]').forEach(button=>button.onclick=()=>run(button,async()=>{await request(`/api/destination-proposals/${encodeURIComponent(button.dataset.proposal)}/${button.dataset.decision}`,{});await list(archived);}));
    root().querySelectorAll('[data-reanalyze]').forEach(button=>button.onclick=()=>run(button,async()=>{
      const started=await request(`/api/destination-proposals/${encodeURIComponent(button.dataset.reanalyze)}/reanalyze`,{});
      let job=started.job;
      button.textContent='Reanalyzing…';
      while(job&&['queued','running'].includes(job.status)){
        await new Promise(resolve=>setTimeout(resolve,850));
        job=await request(`/api/jobs/${encodeURIComponent(job.id)}`);
        button.textContent=job.progress||'Reanalyzing…';
      }
      if(!job||job.status==='failed')throw Error(job?.error||'Reanalysis did not finish');
      const proposal=job.result?.proposals?.[0];
      if(!proposal?.id)throw Error('Analysis finished, but no supplier database matched this quotation.');
      location.hash=`#/proposals/${encodeURIComponent(proposal.id)}`;
    }));
    const render=()=>{const search=document.getElementById('quote-search').value.toLowerCase(), stage=document.getElementById('stage-filter').value;
      const visible=rows.filter(r=>(!stage||r.stage===stage)&&[r.supplier,r.origin,r.destination,r.quote_reference,r.currency].join(' ').toLowerCase().includes(search)&&matchesQuickFilter(r,quickFilter));
      const sort=document.getElementById('quote-sort').value;visible.sort((a,b)=>sort==='received'?b.created_at.localeCompare(a.created_at):String(sort==='supplier'?a.supplier:a.origin+' '+a.destination).localeCompare(String(sort==='supplier'?b.supplier:b.origin+' '+b.destination)));
      const table=document.getElementById('quote-rows');table.innerHTML=visible.map(r=>quoteRow(r,archived)).join('');
      table.querySelectorAll('[data-open-quote]').forEach(row=>{row.addEventListener('click',event=>{if(event.target.closest('a,button'))return;location.hash=row.dataset.openQuote;});row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();location.hash=row.dataset.openQuote;}});});
      document.getElementById('quote-mobile-list').innerHTML=visible.map(r=>quoteMobileCard(r,archived)).join('');
      document.getElementById('quote-empty').hidden=!!visible.length;};
    function matchesQuickFilter(r,filter){if(filter==='all'||filter==='proposals'||filter==='drafts'||filter==='replies')return true;if(filter==='attention')return !!(r.can_approve||r.conflicts.length||r.missing.length||['Reading failed','Needs review','Confirm document type'].includes(r.stage));if(filter==='processing')return r.record_type==='intake'&&['Reading','Received'].includes(r.stage);if(filter==='imported')return r.review_status==='imported';if(filter==='review')return !!r.can_approve;if(filter==='gaps')return !!(r.conflicts.length||r.missing.length);return true;}
    function isParsing(r){return r.record_type==='intake'&&['Received','Reading'].includes(r.stage);}
    function pendingValue(r,label,fields=[]){if(r.record_type==='intake'&&r.proposal_id&&fields.some(name=>r.missing.includes(name)))return `<span class="badge badge-error badge-outline">Missing from quotation</span>`;if(r.record_type==='intake'&&r.stage==='Reading')return `<span class="badge badge-info badge-outline quote-parsing quote-pulse"><span class="loading loading-dots loading-xs" aria-hidden="true"></span><span>AI parsing in progress</span></span>`;if(r.record_type==='intake'&&r.stage==='Received')return `<span class="badge badge-info badge-outline quote-parsing">Queued for AI analysis</span>`;return `<span class="meta">${label}</span>`;}
    function prettyStage(r){if(r.stage==='Received')return ['Queued for AI analysis','badge-info badge-outline'];if(r.stage==='Reading')return ['AI parsing in progress','badge-info'];if(r.stage==='Reading failed')return ['Parsing needs attention','badge-error'];if(r.stage==='Ready for review')return ['Ready for review','badge-success'];if(r.stage==='Imported')return ['Imported','badge-success'];if(r.stage==='Approved')return ['Approved · awaiting import','badge-primary'];if(r.stage==='Missing information')return ['Required information missing','badge-error'];if(r.stage==='Resolve conflicts')return ['Supplier confirmation needed','badge-warning'];if(r.stage==='Needs review'||r.stage==='Confirm document type')return ['Needs review','badge-warning'];if(r.stage==='Analysis complete')return ['Analysis complete','badge-info'];if(r.stage==='Rejected')return ['Rejected','badge-ghost'];return [label(r.stage||'Status unavailable'),'badge-ghost'];}
    function money(r){return r.base_price==null?pendingValue(r,'Price not identified',['Quoted_Price']): `<span class="quote-money">${r.currency?`<span class="meta">${e(r.currency)}</span> `:''}<strong>${e(r.base_price)}</strong>${r.details?.pricing_unit?` <small>/ ${e(label(r.details.pricing_unit))}</small>`:''}</span>`;}
    function routeValue(r){return r.origin&&r.destination?`<span class="quote-route">${e(r.origin)} <span aria-hidden="true">→</span> ${e(r.destination)}</span>`:pendingValue(r,'Route not identified',['Origin_City','Origin_Country','Destination_City','Destination_Country']);}
    function quoteRow(r,isArchived){
      const id=r.record_type==='intake'?null:r.id, sourceId=r.record_type==='intake'?r.id:null;
      const openTarget=r.proposal_id?`#/proposals/${e(r.proposal_id)}`:id?`#/${isArchived?'archived':'quotations'}/${e(id)}`:null;
      const supplier=r.supplier||'Supplier not identified yet', ref=r.record_type==='intake'?'Quotation document':r.quote_reference||'Reference not available';
      const [stage,tone]=prettyStage(r), reading=r.record_type==='intake'&&r.stage==='Reading';
      const complete=r.required===null?'<span class="meta">Completeness available after analysis</span>':`<div class="quote-complete"><progress class="progress progress-primary" max="${Math.max(1,r.required)}" value="${r.filled}" aria-label="Required quotation details identified"></progress><span class="quote-completeness">${r.filled} of ${r.required} details identified</span></div>`;
      const next=r.proposal_id?`<div class="quote-next-action"><a class="btn btn-sm btn-outline" href="#/proposals/${e(r.proposal_id)}">View extraction summary</a>${reading?'<span class="meta">AI is reading</span>':''}</div>`:sourceId?`<div class="quote-next-action"><span class="meta">${reading?'Analysis runs automatically':r.stage==='Received'?'Waiting for AI analysis':e(stage)}</span><a class="link link-primary" href="#/documents/${e(sourceId)}" aria-label="View parsed source for ${e(supplier)}">View parsed source</a></div>`:link(r.id,isArchived?'Inspect':r.can_import?'Import':r.can_approve?'Review quotation':'View details');
      const received=r.created_at?e(new Date(r.created_at).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})):'—';
      return `<tr ${openTarget?`tabindex="0" role="link" aria-label="Open extraction summary for ${e(supplier)}" data-open-quote="${openTarget}" class="quotation-row"`:''}><td><strong>${e(supplier)}</strong><div class="meta quote-ref" title="${e(r.quote_reference||'')}">${e(ref)}</div></td><td>${routeValue(r)}</td><td>${money(r)}</td><td>${received}</td><td>${complete}</td><td><span class="badge badge-sm ${tone} ${reading?'quote-pulse':''}">${reading?'<span class="loading loading-dots loading-xs" aria-hidden="true"></span>':''}${e(stage)}</span>${isArchived?`<div class="meta">${e(r.disposition_reason||r.review_notes||'')}</div>`:''}</td><td>${next}</td></tr>`;
    }
    function quoteMobileCard(r,isArchived){
      const [stage,tone]=prettyStage(r),reading=r.record_type==='intake'&&r.stage==='Reading';
      const sourceId=r.record_type==='intake'?r.id:null;
      const action=r.proposal_id?`<a class="btn btn-sm btn-outline" href="#/proposals/${e(r.proposal_id)}">View extraction summary</a>`:sourceId?`<a class="link link-primary" href="#/documents/${e(sourceId)}">View parsed source</a>`:link(r.id,isArchived?'Inspect':r.can_import?'Import':r.can_approve?'Review quotation':'View details');
      return `<article class="card bg-base-100 border border-base-300 quote-mobile-item"><div class="card-body"><div class="quote-mobile-heading"><div><strong>${e(r.supplier||'Supplier not identified yet')}</strong><div class="meta">${e(r.record_type==='intake'?'Quotation document':r.quote_reference||'Reference not available')}</div></div><span class="badge badge-sm ${tone} ${reading?'quote-pulse':''}">${reading?'<span class="loading loading-dots loading-xs" aria-hidden="true"></span>':''}${e(stage)}</span></div><p>${routeValue(r)}</p><div class="quote-mobile-meta"><span>${money(r)}</span><span>${r.created_at?e(new Date(r.created_at).toLocaleDateString()):'—'}</span></div><div class="quote-mobile-footer">${completeMobile(r)}${action}</div></div></article>`;
    }
    function completeMobile(r){return r.required===null?'<span class="meta">Completeness after analysis</span>':`<span class="meta">${r.filled} / ${r.required} details identified</span>`;}
    document.getElementById('quote-search').oninput=render; document.getElementById('stage-filter').onchange=render;document.getElementById('quote-sort').onchange=render;
    const filterTabs=[...root().querySelectorAll('[data-quote-filter]')];
    const tabTone={all:'badge-ghost',attention:'badge-warning',processing:'badge-info',imported:'badge-success'};
    const syncFilterTabs=filter=>filterTabs.forEach(tab=>{const selected=tab.dataset.quoteFilter===filter;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;tab.classList.toggle('tab-active',selected);const badge=tab.querySelector('.badge');if(badge){badge.classList.remove('badge-primary','badge-warning','badge-info','badge-success','badge-ghost');badge.classList.add(selected?'badge-primary':tabTone[tab.dataset.quoteFilter]||'badge-ghost');}});
    const selectFilter=(filter,scroll=true)=>{activeFilter=filter;quickFilter=filter;syncFilterTabs(filter);render();if(scroll)document.querySelector('.quote-list-head')?.scrollIntoView({behavior:'smooth',block:'start'});};
    filterTabs.forEach(tab=>tab.addEventListener('click',()=>selectFilter(tab.dataset.quoteFilter,false)));
    root().querySelector('[role="tablist"]')?.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const current=filterTabs.indexOf(document.activeElement);const index=event.key==='Home'?0:event.key==='End'?filterTabs.length-1:(current+(event.key==='ArrowRight'?1:-1)+filterTabs.length)%filterTabs.length;filterTabs[index].focus();selectFilter(filterTabs[index].dataset.quoteFilter,false);});
    root().querySelectorAll('[data-quick-filter]').forEach(button=>button.onclick=()=>{if(button.dataset.actionHref){location.hash=button.dataset.actionHref;return;}if(button.dataset.quickFilter==='proposals'){const box=document.getElementById('proposal-workspace');if(box){box.open=true;box.scrollIntoView({behavior:'smooth',block:'center'});}document.querySelector('.proposal-item:not([open])')?.setAttribute('open','');return;}const filter=button.dataset.quickFilter;activeFilter=['review','gaps'].includes(filter)?'attention':filter;quickFilter=filter;syncFilterTabs(activeFilter);render();document.querySelector('.quote-list-head')?.scrollIntoView({behavior:'smooth',block:'start'});});
    selectFilter('all',false);
  }
  async function proposal(id) {
    const [p, drafts] = await Promise.all([
      request(`/api/destination-proposals/${encodeURIComponent(id)}`),
      request('/api/supplier-email-drafts'),
    ]);
    const values=p.values||{},missing=p.missing||[],uncertain=p.uncertain||[];
    const statusLabel=({ready_for_approval:'Ready for your approval',approved:'Approved · awaiting import',imported:'Imported successfully',rejected:'Rejected',needs_information:'Information needed',failed:'Analysis failed'}[p.status]||label(p.status||'Status unavailable'));
    const statusTone=p.status==='imported'?'badge-success':p.status==='approved'?'badge-info':p.status==='ready_for_approval'?'badge-warning':p.status==='needs_information'?'badge-error':p.status==='failed'?'badge-error':'badge-ghost';
    const tone=(status,hasValue)=>status==='supplier_master'&&!hasValue?'badge-neutral':({high_confidence:'badge-success',uncertain:'badge-warning',missing:'badge-error',not_applicable:'badge-ghost',supplier_master:'badge-info',system_metadata:'badge-ghost'}[status]||'badge-neutral');
    const statusText=(status,hasValue)=>status==='supplier_master'?(hasValue?'Supplier master · context only':'Supplier master · not stated'):({high_confidence:'Green · found with evidence',uncertain:'Yellow · needs confirmation',missing:'Red · required information not stated',not_applicable:'Not applicable',system_metadata:'System generated',not_stated:'Not stated · optional'}[status]||'Not stated · optional');
    const fields=(p.schema||[]).filter(f=>f.scope!=='system').map(f=>{
      const name=f.name,raw=values[name],status=p.field_status?.[name]|| (missing.includes(name)?'missing':uncertain.includes(name)?'uncertain':raw!=null&&raw!==''?'high_confidence':'not_stated');
      const value=status==='missing'?'Not stated in quotation':status==='not_applicable'?'Not applicable':raw==null||raw===''?'Not stated':String(raw);
      const score=p.confidence?.[name],evidence=p.evidence?.[name],reason=p.explanations?.[name];
      const hasValue=raw!=null&&raw!=='';
      return `<tr><th scope="row"><strong>${e(f.label||name.replaceAll('_',' '))}</strong>${f.required?' <span class="badge badge-xs badge-error">Required</span>':''}</th><td>${e(value)}${score!=null&&['high_confidence','uncertain'].includes(status)?` <span class="badge badge-sm badge-outline">${Math.round(Number(score)*100)}% confidence</span>`:''}</td><td><span class="badge badge-sm ${tone(status,hasValue)}">${e(statusText(status,hasValue))}</span>${reason?`<p class="meta">${e(reason)}</p>`:''}${evidence?`<details class="mt-2"><summary>Evidence from source</summary><blockquote class="source-evidence">${e(evidence)}</blockquote></details>`:status==='missing'?'<p class="meta">A supplier clarification draft should be available below.</p>':''}</td></tr>`;
    }).join('');
    const attached=drafts.filter(d=>d.destination_proposal_id===p.id&&d.status!=='cancelled');
    const title=values.Supplier_Name||values.Quotation_Reference||p.source_name||'Quotation extraction';
    const route=[values.Origin_City,values.Origin_Country].filter(Boolean).join(', ')+' → '+[values.Destination_City,values.Destination_Country].filter(Boolean).join(', ');
    const reanalyze=async button=>run(button,async()=>{
      const started=await request(`/api/destination-proposals/${encodeURIComponent(p.id)}/reanalyze`,{});let job=started.job;
      button.textContent='Reanalyzing…';
      while(job&&['queued','running'].includes(job.status)){await new Promise(resolve=>setTimeout(resolve,850));job=await request(`/api/jobs/${encodeURIComponent(job.id)}`);button.textContent=job.progress||'Reanalyzing…';}
      if(!job||job.status==='failed')throw Error(job?.error||'Reanalysis did not finish');
      const latest=job.result?.proposals?.[0];if(!latest?.id)throw Error('Analysis finished, but no supplier database matched this quotation.');
      location.hash=`#/proposals/${encodeURIComponent(latest.id)}`;
    });
    heading('Extraction summary',`${p.database_name||'Supplier Master Database'} · ${p.source_name||'Quotation source'}`);
    frame(`<div class="workspace-toolbar detail-toolbar"><a class="btn btn-ghost btn-sm" href="#/quotations">← Back to quotations</a><span class="badge ${statusTone}">${e(statusLabel)}</span></div>
      ${!p.schema_current?`<div class="alert alert-warning"><span>This proposal was extracted with an older supplier database schema, so its results may omit current fields.</span><button class="btn btn-sm btn-warning" id="reanalyze-proposal">Reanalyze with current fields</button></div>`:''}
      <section class="card bg-base-100 border border-base-300 proposal-summary-card"><div class="card-body"><p class="quote-kicker">QUOTATION SUMMARY</p><h2 class="card-title">${e(title)}</h2><p>${e(route.trim()==='→'?'Route not identified':route)}</p><p class="meta">Source: ${e(p.source_name||'Email attachment')} · Destination: ${e(p.database_name||'Supplier Master Database')}</p><div class="stats stats-vertical sm:stats-horizontal bg-base-200 proposal-summary-stats"><div class="stat"><div class="stat-title">Required details found</div><div class="stat-value text-primary">${(p.schema||[]).filter(f=>f.required).length-missing.length} / ${(p.schema||[]).filter(f=>f.required).length}</div></div><div class="stat"><div class="stat-title">Missing</div><div class="stat-value ${missing.length?'text-error':'text-success'}">${missing.length}</div></div><div class="stat"><div class="stat-title">Needs confirmation</div><div class="stat-value ${uncertain.length?'text-warning':'text-success'}">${uncertain.length}</div></div></div></div></section>
      ${p.issues?.length?`<div class="alert alert-warning"><div><strong>Analysis notes</strong>${p.issues.map(note=>`<p>${e(note)}</p>`).join('')}</div></div>`:''}
      <section class="panel proposal-summary-fields"><div class="row spread"><div><h2>Extracted quotation details</h2><p class="meta">Green means supported by source evidence. Yellow needs supplier confirmation. Red means a required field was not stated.</p></div><span class="badge badge-outline">${fields?((p.schema||[]).filter(f=>f.scope!=='system').length):0} fields</span></div><div class="overflow-x-auto"><table class="table table-zebra"><thead><tr><th>Field</th><th>Extracted value</th><th>Status and evidence</th></tr></thead><tbody>${fields}</tbody></table></div></section>
      <section class="panel proposal-summary-drafts"><div class="row spread"><div><h2>Automatically prepared supplier drafts</h2><p class="meta">Drafts are saved locally; review and explicitly approve before sending.</p></div><a class="btn btn-sm btn-outline" href="#/drafts">All drafts</a></div>${attached.length?attached.map(d=>`<article class="workspace-gap row spread"><div><span class="badge badge-sm ${d.draft_type==='supplier_confirmation'?'badge-warning':'badge-error'}">${e(d.draft_type==='supplier_confirmation'?'Supplier confirmation':'Missing information')}</span><p><strong>${e(d.subject)}</strong></p><p class="meta">${d.resolution_status==='solved'?'<span class="badge badge-success">Solved</span>':d.resolution_status==='follow_up_required'?'<span class="badge badge-warning">Reply received · details still needed</span>':d.resolution_status==='awaiting_reply'?'<span class="badge badge-info">Sent · awaiting reply</span>':e(d.status)} · ${e(d.recipient)}</p></div><a class="btn btn-sm btn-primary" href="#/email-draft/${e(d.id)}">${d.status==='sent'?'View message':'Review draft'}</a></article>`).join(''):missing.length||uncertain.length?'<div class="alert alert-warning"><span>No email draft is attached yet. Check that Gmail is connected and the source email has a valid sender address, then reopen or reanalyze this proposal.</span></div>':'<div class="alert alert-success"><span>No supplier follow-up is needed for the fields currently marked required.</span></div>'}</section>
      <section class="panel"><h2>Record decision</h2><p class="meta">Import is separate from approval. No record is written to the supplier database until you approve and import it.</p><div class="row">${p.status==='ready_for_approval'?`<button class="btn btn-primary" data-proposal="${e(p.id)}" data-decision="approve">Approve record</button>`:''}${p.status==='approved'?`<button class="btn btn-primary" data-proposal="${e(p.id)}" data-decision="import">Import approved record</button>`:''}${!['imported','rejected'].includes(p.status)?`<button class="btn btn-ghost" data-proposal="${e(p.id)}" data-decision="reject">Reject quotation record</button>`:''}${p.status==='imported'?'<span class="badge badge-success">Already imported</span>':''}</div></section>
      ${p.previous_versions?.length?`<details class="panel"><summary>Earlier analysis versions (${p.previous_versions.length})</summary><ul class="list-disc pl-6">${p.previous_versions.map(v=>`<li>${e(v.created_at||'Earlier version')} · ${e(v.database_name||'Supplier database')} · ${e(v.status)}${v.schema_current?' · current schema':''}</li>`).join('')}</ul><p class="meta">Earlier versions are retained as history.</p></details>`:''}`);
    root().querySelector('#reanalyze-proposal')?.addEventListener('click',event=>reanalyze(event.currentTarget));
    root().querySelectorAll('[data-proposal]').forEach(button=>button.onclick=()=>run(button,async()=>{await request(`/api/destination-proposals/${encodeURIComponent(button.dataset.proposal)}/${button.dataset.decision}`,{});await proposal(id);}));
  }
  function archiveDecision(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='archive-dialog';dialog.innerHTML='<form method="dialog" class="supplier-form"><h2>Reject or archive quotation</h2><p>The original quotation, correspondence and history are preserved.</p><label>Decision<select name="disposition"><option value="rejected">Reject quotation</option><option value="invalid">Mark invalid or unusable</option><option value="archived">Archive closed quotation</option></select></label><label>Reason<select name="reason_code"><option value="price">Price</option><option value="terms">Unusable terms</option><option value="withdrawn">Supplier withdrew offer</option><option value="expired">Expired</option><option value="duplicate">Duplicate</option><option value="closed">Shipment closed</option><option value="other">Other</option></select></label><label>Explanation<textarea name="reason" rows="3" required autofocus></textarea></label><div class="row"><button type="button" class="btn neutral" id="cancel-archive">Cancel</button><button class="btn" type="submit">Preserve in archive</button></div></form>';document.body.append(dialog);dialog.querySelector('#cancel-archive').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));dialog.close();resolve(data);};dialog.onclose=()=>{dialog.remove();resolve(null);};dialog.showModal();});}
  async function detail(id) {
    const data=await request(`/api/workspace/quotes/${encodeURIComponent(id)}`),q=data.quotation;
    heading(data.supplier || 'Quotation review',`${q.origin && q.destination?`${q.origin} → ${q.destination}`:'Route not extracted yet'} · ${q.quote_reference || 'Reference not available'}`);
    const archived=!!q.disposition||q.review_status==='rejected';
    const sourceHTML=s=>{let text=e(s.text);const snippets=data.fields.flatMap(f=>f.evidence).filter(v=>v.source_filename===s.filename&&v.validation_status==='accepted').map(v=>v.snippet).sort((a,b)=>b.length-a.length);for(const snippet of [...new Set(snippets)]){const escaped=e(snippet);if(escaped)text=text.replace(escaped,'<mark>'+escaped+'</mark>');}return text;};
    const fieldLabel=name=>({carrier_name:'Supplier',quote_reference:'Quotation reference',origin:'Origin',destination:'Destination',base_price:'Quoted price',currency:'Currency',pricing_unit:'Price basis',valid_until:'Valid until',total_known_cost:'Known total',transit_time_days_min:'Minimum transit time',transit_time_days_max:'Maximum transit time',delivery_scope:'Delivery scope',payment_terms:'Payment terms',included_services:'Included services',excluded_services:'Excluded services',insurance:'Insurance',customs:'Customs',transport_mode:'Transport mode'}[name]||label(name));
    const groupFields=(names)=>data.fields.filter(f=>names.includes(f.field));
    const fieldTable=fields=>`<div class="table-scroll"><table class="workspace-table quotation-fields"><thead><tr><th>Detail</th><th>Extracted value and confidence</th><th>Status and source evidence</th></tr></thead><tbody>${fields.map(f=>{
      const scores=f.evidence.map(v=>v.confidence).filter(v=>typeof v==='number');
      const score=scores.length?Math.min(...scores):null;
      const unresolved=f.evidence.some(v=>v.validation_status==='needs_review')||score!==null&&score<.70;
      const missing=f.value==null&&f.required;
      const notStated=f.value==null&&!f.required&&!f.not_applicable;
      const notApplicable=!!f.not_applicable;
      const tone=missing?'badge-error':unresolved?'badge-warning':score!==null?'badge-success':notApplicable?'badge-ghost':'badge-neutral';
      const status=missing?'Red · missing from quotation':unresolved?'Yellow · needs confirmation':score!==null?'Green · high confidence':notApplicable?'Not applicable':notStated?'Not stated':f.status;
      const confidence=score===null?'':` <span class="badge badge-sm ${tone}">${Math.round(score*100)}%</span>`;
      const displayValue=missing?'Missing from quotation':notApplicable?'Not applicable':notStated?'Not stated':e(f.value);
      return `<tr id="quote-field-${e(f.field)}" data-quote-field="${e(f.field)}" class="${missing?'field-not-found':''}"><td><strong>${e(fieldLabel(f.field))}</strong></td><td>${displayValue}${!missing&&!notStated&&!notApplicable?confidence:''}</td><td><span class="badge badge-sm ${tone}">${e(status)}</span>${missing?'<p class="meta">Supplier clarification is required.</p>':''}${f.evidence.length?`<details><summary>${f.evidence.length} source ${f.evidence.length===1?'excerpt':'excerpts'}</summary>${f.evidence.map(v=>`<blockquote>${e(v.snippet)}<footer>${e(v.source_filename)} ${e(v.page_or_sheet||'')}</footer>${v.explanation?`<small>${e(v.explanation)}</small>`:''}</blockquote>${v.validation_status==='needs_review'&&!archived?`<button class="btn neutral" data-resolve="${e(v.id)}" data-use="false">Keep existing value</button><button class="btn" data-resolve="${e(v.id)}" data-use="true">Use this value</button>`:''}`).join('')}</details>`:'<span class="meta">No supporting source excerpt</span>'}</td></tr>`;
    }).join('')}</tbody></table></div>`;
    const fieldGroups=[['Supplier information',['carrier_name','quote_reference']],['Freight route',['origin','destination']],['Pricing and payment terms',['base_price','currency','pricing_unit','total_known_cost','valid_until','payment_terms']],['Transport details',['transit_time_days_min','transit_time_days_max','delivery_scope','transport_mode','included_services','excluded_services','insurance','customs']]];
    const groupedNames=fieldGroups.flatMap(([,names])=>names); const otherFields=data.fields.filter(f=>!groupedNames.includes(f.field));
    const statusText=data.stage || q.disposition || ({extracted:'Awaiting review',approved:'Approved · awaiting import',imported:'Imported',rejected:'Rejected'}[q.review_status]||'Needs review');
    frame(`<div class="workspace-toolbar detail-toolbar"><a href="#/${archived?'archived':'quotations'}">← All quotations</a><span class="supplier-status">${e(statusText)}</span><span class="meta">Version ${q.version}</span>${!archived&&data.can_clarify?'<button class="supplier-btn supplier-btn-primary" id="clarify">Prepare clarification draft</button>':''}</div>
      ${data.shipment?.status==='needs_review'&&!archived?`<section class="note warn"><strong>Confirm the proposed shipment route</strong><p>${e(data.shipment.origin)} → ${e(data.shipment.destination)}</p><button class="btn" id="confirm-shipment">Confirm route</button><button class="btn neutral" id="correct-shipment">Correct route</button></section>`:''}<div class="workspace-tabs" role="tablist">${['Summary','Missing information','Correspondence','Source documents','History'].map((t,i)=>`<button role="tab" id="quote-tab-${i}" aria-controls="quote-panel-${i}" tabindex="${i?-1:0}" aria-selected="${!i}" data-tab="${i}">${t}</button>`).join('')}</div>
      <section data-section="0" class="panel quotation-summary"><div class="quotation-summary-head"><div><p class="quote-kicker">QUOTATION OVERVIEW</p><h2>Extracted details</h2><p>Values below come from the received quotation. Missing information stays clearly marked.</p></div><span class="supplier-status ${data.can_approve?'ok':'pending'}">${data.can_approve?'Ready for review':'Review in progress'}</span></div>${fieldGroups.map(([title,names])=>{const fields=groupFields(names);const groupId=title==='Pricing and payment terms'?'commercial-terms':title==='Transport details'?'transport-details':title==='Freight route'?'freight-route':'supplier-information';return fields.length?`<details id="quote-group-${groupId}" class="quote-detail-group" ${title==='Freight route'?'open':''}><summary><strong>${title}</strong><span>${fields.filter(f=>f.value!=null).length} of ${fields.length} identified</span></summary>${fieldTable(fields)}</details>`:''}).join('')}${otherFields.length?`<details id="quote-group-other" class="quote-detail-group"><summary><strong>Other extracted information</strong><span>${otherFields.length} fields</span></summary>${fieldTable(otherFields)}</details>`:''}<details class="quote-detail-group ai-analysis"><summary><strong>AI analysis and source evidence</strong><span>${data.conflicts.length?`${data.conflicts.length} items need review`:'Evidence checked'}</span></summary><div class="ai-analysis-body"><p>The quotation has been checked against its original source. Unverified or missing values are not treated as confirmed facts.</p>${data.conflicts.length?`<div class="note warn"><strong>Evidence needs review</strong><p>${e(data.conflicts.map(fieldLabel).join(', '))}</p></div>`:'<span class="supplier-status ok">No unresolved evidence conflicts</span>'}${data.destination?`<p>Matched Supplier Master: <strong>${e(data.destination.database_name||'Destination selected')}</strong>. Supplier master values stay separate from quotation evidence.</p>`:''}</div></details>${!archived&&q.review_status!=='imported'?`<details class="quote-detail-group destination-tools"><summary><strong>Supplier Master match</strong><span>${data.destination?e(data.destination.database_name||'Matched'): 'Automatic match pending'}</span></summary><div class="destination-content">${data.destination?`<p>This proposal is linked to the canonical Supplier Master Database. Existing supplier details provide context only; they do not count as quotation evidence.</p><dl>${Object.entries(data.destination.database_matches||{}).map(([k,v])=>`<dt>${e(fieldLabel(k))}</dt><dd>${e(v)} · existing supplier value</dd>`).join('')||'<p>No existing supplier profile fields matched.</p>'}</dl><form id="destination-form" class="supplier-form"><h3>Proposed supplier and quotation row</h3>${[...new Set([...Object.keys(data.destination.proposed_row||{}),...(data.destination.missing_fields||[]).map(f=>f.field)])].map(key=>`<label>${e(fieldLabel(key))}<input data-destination-field="${e(key)}" value="${e(data.destination.proposed_row?.[key]||'')}"></label>`).join('')}<button class="btn neutral">Save corrections</button></form>`:'<p>This quotation is matched automatically against the one canonical Supplier Master Database. The proposal will appear here when matching completes.</p>'}<a href="#/supplier">Open Supplier Master and Gmail connections</a></div></details>`:''}</section>
      <section data-section="1" class="panel" hidden><h2>Missing information</h2>${(data.blocking_reasons||[]).map(reason=>`<p class="note warn">${e(reason)}</p>`).join('')}<ul>${data.missing.map(f=>`<li id="missing-field-${e(f)}" tabindex="-1">${e(fieldLabel(f))} — not identified in the quotation ${!archived?`<button class="btn neutral" data-waive-field="${e(f)}">Waive with reason</button>`:''}</li>`).join('') || '<li>No required fields missing.</li>'}</ul><h3>Validation and conflicts</h3>${data.gaps.filter(g=>g.status==='open').map(g=>`<div class="workspace-gap"><p>${e(g.description)}</p>${!archived?`<button class="btn neutral" data-waive="${e(g.id)}">Waive with reason</button>`:''}</div>`).join('') || '<p>No open validation gaps.</p>'}</section>
      <section data-section="2" class="panel" hidden><h2>Correspondence</h2>${!archived?'<button class="btn neutral" id="record-manual-send">Record external sending confirmation</button>':''}<p>${e(data.subject || 'Original quotation')} · ${e(data.sender || 'Sender not available')}</p>${data.correspondence.map(t=>`<article class="workspace-gap">${(data.local_drafts||[]).find(d=>d.id===t.id)?`<details><summary>Saved clarification email</summary><pre class="source-text">${e(data.local_drafts.find(d=>d.id===t.id).body)}</pre></details>`:''}<ol>${t.questions.map(q=>`<li>${e(q.text)}</li>`).join('')}</ol>${t.reply?`<blockquote>${e(t.reply)}</blockquote>`:!archived?`<label>Supplier response<textarea data-answer="${e(t.id)}" rows="4" placeholder="Paste the supplier’s response, including short or numbered answers"></textarea></label><button class="btn" data-submit-answer="${e(t.id)}">Interpret response</button>`:''}</article>`).join('') || '<p>No clarification questions yet.</p>'}</section>
      <section data-section="3" class="panel" hidden><h2>Original documents</h2><p class="meta">Review the source text and evidence when you need more context.</p>${data.sources.map(s=>`<details><summary>${e(s.filename)} · ${e(s.kind)}</summary>${s.location?`<p class="meta">${e(s.location)}</p>`:''}${s.error?`<p class="note bad">Could not parse this source: ${e(s.error)}. Re-upload a readable copy or archive the unusable quotation.</p>`:''}<pre class="source-text">${sourceHTML(s)}</pre></details>`).join('')}</section>
      <section data-section="4" class="panel" hidden><h2>Processing and review history</h2>${data.history.length?`<ul class="timeline timeline-vertical quote-history">${data.history.map(a=>`<li><hr><div class="timeline-start quote-history-date">${e(new Date(a.created_at).toLocaleString())}</div><div class="timeline-middle"><span class="status status-primary"></span></div><div class="timeline-end"><details><summary>${e(label(a.action))}</summary><pre class="source-text">${e(a.details_json)}</pre></details></div><hr></li>`).join('')}</ul>`:'<p>No decisions recorded yet.</p>'}<details class="quote-detail-group"><summary><strong>Preserved quotation versions</strong><span>${data.versions.length} versions</span></summary>${data.versions.map(v=>`<details><summary>Version ${v.version}</summary><pre class="source-text">${e(v.snapshot_json)}</pre></details>`).join('')||'<p>No previous versions.</p>'}</details></section>
      ${!archived?`<footer class="workspace-footer"><div><strong>Review and import are separate</strong><p>Resolve missing information and conflicts before approval.</p></div><button id="approve-quote" class="btn" ${!data.can_approve||q.review_status!=='extracted'?'disabled':''}>Approve quotation</button><button id="import-quote" class="btn" title="Approve the quotation first" ${q.review_status!=='approved'?'disabled':''}>Import quotation</button><button id="archive-quote" class="btn neutral">Reject or archive</button></footer>`:`<div class="note">${e(q.disposition_reason || 'Archived')}</div>`}`);
    root().querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{root().querySelectorAll('[data-tab]').forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1;});root().querySelectorAll('[data-section]').forEach(s=>s.hidden=s.dataset.section!==b.dataset.tab);});
    root().querySelectorAll('[data-section]').forEach(section=>{section.id='quote-panel-'+section.dataset.section;section.setAttribute('role','tabpanel');section.setAttribute('aria-labelledby','quote-tab-'+section.dataset.section);});
    root().querySelector('[role="tablist"]').onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...root().querySelectorAll('[data-tab]')];const current=tabs.indexOf(document.activeElement);const index=event.key==='Home'?0:event.key==='End'?tabs.length-1:(current+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[index].focus();tabs[index].click();};
    const deepLink=new URLSearchParams(location.hash.split('?')[1]||'').get('highlight');
    if(deepLink)requestAnimationFrame(()=>{
      if(deepLink==='missing'){
        root().querySelector('[data-tab="1"]')?.click();
        const items=[...root().querySelectorAll('[id^="missing-field-"]')];
        items.forEach(item=>item.classList.add('assistant-highlight'));
        (items[0]||root().querySelector('[data-section="1"]'))?.scrollIntoView({behavior:'smooth',block:'center'});
        items[0]?.focus({preventScroll:true});
        return;
      }
      root().querySelector('[data-tab="0"]')?.click();
      const row=document.getElementById(`quote-field-${deepLink}`);
      if(!row)return;
      const group=row.closest('details');if(group)group.open=true;
      row.classList.add('assistant-highlight');row.tabIndex=-1;
      row.scrollIntoView({behavior:'smooth',block:'center'});row.focus({preventScroll:true});
    });
    const op=(name,body={})=>request(`/api/workspace/quotes/${id}/${name}`,body);
    document.getElementById('destination-form')?.addEventListener('submit',event=>{event.preventDefault();run(event.submitter,async()=>{const proposed_row=Object.fromEntries([...event.target.querySelectorAll('[data-destination-field]')].map(input=>[input.dataset.destinationField,input.value]));const response=await fetch(`/api/supplier-actions/${data.destination.id}/proposal`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({proposed_row,notes:'Corrected in the quotation review workspace'})});const result=await response.json();if(!response.ok)throw Error(result.error);await detail(id);notice('Destination proposal updated; review approval is required again.');});});
    document.getElementById('confirm-shipment')?.addEventListener('click',event=>run(event.target,async()=>{await request('/api/action',{action:'shipment.approve',id:data.shipment.id,expected_updated_at:data.shipment.updated_at});await detail(id);}));
    document.getElementById('correct-shipment')?.addEventListener('click',event=>run(event.target,async()=>{const origin=prompt('Correct origin',data.shipment.origin);if(!origin)return;const destination=prompt('Correct destination',data.shipment.destination);if(!destination)return;await request('/api/action',{action:'shipment.edit',id:data.shipment.id,fields:{origin,destination}});await detail(id);}));
    document.getElementById('approve-quote')?.addEventListener('click',event=>run(event.target,async()=>{await op('approve');await detail(id);}));
    document.getElementById('import-quote')?.addEventListener('click',event=>run(event.target,async()=>{await op('import');await detail(id);}));
    document.getElementById('archive-quote')?.addEventListener('click',event=>run(event.target,async()=>{const decision=await archiveDecision();if(!decision)return;await op('archive',decision);location.hash='#/archived';}));
    document.getElementById('clarify')?.addEventListener('click',event=>run(event.target,async()=>{const turn=await op('questions');sessionStorage.setItem('quotation-turn-'+id,turn.id);location.hash='#/draft/'+id;}));
    root().querySelectorAll('[data-waive-field]').forEach(b=>b.onclick=()=>run(b,async()=>{const reason=prompt('Why can this required field be waived?');if(!reason)return;await op('waive-field',{field:b.dataset.waiveField,reason});await detail(id);}));
    root().querySelectorAll('[data-waive]').forEach(b=>b.onclick=()=>run(b,async()=>{const reason=prompt('Why can this gap be waived?');if(!reason)return;await request('/api/action',{action:'gap.waive',id:b.dataset.waive,reason});await detail(id);}));
    root().querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>run(b,async()=>{const reason=prompt('Explain this conflict decision');if(!reason)return;await op('resolve',{evidence_id:b.dataset.resolve,use_candidate:b.dataset.use==='true',reason});await detail(id);}));
    document.getElementById('record-manual-send')?.addEventListener('click',event=>run(event.target,async()=>{await op('confirmation');await detail(id);root().querySelector('[data-tab="2"]').click();}));
    root().querySelectorAll('[data-submit-answer]').forEach(b=>b.onclick=()=>run(b,async()=>{const text=root().querySelector(`[data-answer="${b.dataset.submitAnswer}"]`).value;const result=await op('answer',{turn_id:b.dataset.submitAnswer,text});await detail(id);notice(result.message);}));
  }
  async function dashboard(){
    const [rows,activity,gmail,messages,proposals]=await Promise.all([request('/api/workspace/quotes?include_intake=true'),request('/api/notifications'),request('/api/gmail/status'),request('/api/gmail/inbox'),request('/api/destination-proposals')]);
    heading('Overview','A clear view of quotation work, supplier decisions and mailbox activity.');
    const review=rows.filter(r=>r.can_approve).length,processing=rows.filter(r=>r.record_type==='intake'&&r.stage==='Reading').length,missing=rows.filter(r=>r.missing.length||r.conflicts.length).length,completed=rows.filter(r=>r.review_status==='imported').length;
    const activeMail=messages.filter(m=>!['not_a_quotation','ignored'].includes(m.processing_status));
    const replyLinking=activeMail.filter(m=>m.processing_status==='reply_needs_linking').length;
    const activeMessages=activeMail.length;
    const quotationAttachments=activeMail.filter(m=>m.classification==='NEW_QUOTATION').reduce((total,m)=>total+(m.attachment_count||0),0);
    const needsImport=proposals.filter(p=>p.status==='approved').length;
    const tasks=[...rows.filter(r=>r.can_approve||r.missing.length||r.conflicts.length).map(r=>({title:r.supplier||'Quotation review',body: r.can_approve?'Quotation is ready for your review':r.conflicts.length?'Source evidence needs review':'Some quotation details were not found',href:r.proposal_id?`#/proposals/${e(r.proposal_id)}`:r.record_type==='intake'?'#/inbox':`#/quotations/${e(r.id)}`,label:r.proposal_id?'Review extraction summary':r.can_approve?'Review quotation':'Resolve details'})),...(replyLinking?[{title:`${replyLinking} supplier ${replyLinking===1?'reply':'replies'}`,body:'Choose the quotation each reply belongs to.',href:'#/inbox',label:'Link replies'}]:[]),...(needsImport?[{title:`${needsImport} approved database ${needsImport===1?'record':'records'}`,body:'Review approval is complete; import remains a separate action.',href:'#/quotations',label:'Open proposals'}]:[])];
    const statusLabel=activity.queue.reading_message_id?'AI is reading a quotation':activity.queue.queued?`${activity.queue.queued} message(s) queued for review`:gmail.error?'Gmail sync needs attention':'Mailbox ready';
    frame(`<header class="dashboard-welcome"><div><p class="quote-kicker">FREIGHT OPERATIONS</p><h2>Good to see you</h2><p>Review the work that needs a decision and see what the agent has completed.</p></div><a class="btn btn-primary dashboard-mailbox-cta" href="#/inbox">Open Mailbox <span aria-hidden="true">→</span></a></header>
      <section class="dashboard-section"><div class="dashboard-section-title"><div><h3>Overview</h3><p>Current quotation workload</p></div><a href="#/quotations">View all quotations</a></div><div class="dashboard-stats quote-stats"><a href="#/quotations" class="stat dashboard-stat"><span class="stat-title">Total received</span><span class="stat-value">${rows.length}</span><span class="stat-desc">Quotations and documents</span></a><a href="#/quotations" class="stat dashboard-stat"><span class="stat-title">Processing</span><span class="stat-value">${processing}</span><span class="stat-desc">AI document analysis</span></a><a href="#/quotations" class="stat dashboard-stat"><span class="stat-title">Awaiting review</span><span class="stat-value">${review}</span><span class="stat-desc">Human approval needed</span></a><a href="#/quotations" class="stat dashboard-stat"><span class="stat-title">Needs information</span><span class="stat-value">${missing}</span><span class="stat-desc">Missing or conflicting details</span></a><a href="#/quotations" class="stat dashboard-stat"><span class="stat-title">Completed</span><span class="stat-value">${completed}</span><span class="stat-desc">Imported quotations</span></a></div></section>
      <div class="dashboard-grid"><section class="dashboard-section action-required"><div class="dashboard-section-title"><div><h3>Action required</h3><p>Only items that need your input</p></div><span class="supplier-status ${tasks.length?'pending':'ok'}">${tasks.length?`${tasks.length} actions`:'All clear'}</span></div>${tasks.length?`<div class="dashboard-task-list">${tasks.slice(0,6).map(t=>`<article class="dashboard-task"><span class="attention-indicator"></span><div><strong>${e(t.title)}</strong><p>${e(t.body)}</p></div><a class="btn btn-sm btn-outline" href="${t.href}">${e(t.label)}</a></article>`).join('')}</div>`:'<div class="dashboard-clear"><span class="status status-success"></span><p>Nothing needs your attention right now.</p></div>'}</section>
      <section class="dashboard-section mailbox-overview-card"><div class="dashboard-section-title"><div><h3>Mailbox</h3><p>Email intake and supplier replies</p></div><span class="supplier-status ${gmail.accounts?.some(a=>a.status==='connected')?'ok':'plain'}">${gmail.accounts?.some(a=>a.status==='connected')?'Connected':'Not connected'}</span></div><div class="mailbox-mini-stats"><div><strong>${activeMessages}</strong><small>Active messages</small></div><div><strong>${quotationAttachments}</strong><small>Quotation attachments</small></div><div><strong>${replyLinking}</strong><small>Replies to link</small></div></div><p class="mailbox-last-sync">${gmail.last_successful_sync_at?`Last successful sync ${e(new Date(gmail.last_successful_sync_at).toLocaleString())}`:'No successful synchronization recorded'}</p><p class="mailbox-sync-health"><span class="status ${gmail.error?'status-warning':gmail.running?'status-info':'status-success'}"></span>${e(statusLabel)}${gmail.error?`: ${e(gmail.error)}`:''}</p><a class="btn btn-primary" href="#/inbox">Open Mailbox</a></section></div>
      <section class="dashboard-section recent-activity"><div class="dashboard-section-title"><div><h3>Recent activity</h3><p>Latest email, analysis and approval events</p></div><a href="#/notifications">View notifications</a></div>${activity.items.length?`<ul class="timeline timeline-vertical activity-timeline">${activity.items.slice(0,6).map((item,index)=>`<li><hr class="${index?'':'activity-first'}"><div class="timeline-start meta">${e(item.time||'')}</div><div class="timeline-middle"><span class="status ${['Ready for approval','Imported','Action recorded'].includes(item.status)?'status-success':['Needs review','Information missing','Reply needs linking'].includes(item.status)?'status-warning':'status-info'}"></span></div><a class="timeline-end timeline-box activity-event" href="${e(item.href||'#/notifications')}"><span class="row spread"><strong>${e(item.title)}</strong><span class="badge badge-sm badge-outline">${e(item.status)}</span></span><small>${e(item.diagnostic||'Open activity for details')}</small></a><hr class="${index===Math.min(activity.items.length,6)-1?'activity-last':''}"></li>`).join('')}</ul>`:'<p class="meta">No quotation activity has been recorded yet.</p>'}</section>`);
  }
  return {list, detail, proposal, dashboard, e, request, frame, heading, run, notice};
})();
